import grackle.Predicate.{Const, Eql}
import grackle.Query.{Filter, Limit, Offset, OrderBy, OrderSelection, OrderSelections}
import grackle.Value.{AbsentValue, IntValue, NullValue}

def mkOffset(query: Query, v: Value): Result[Query] = v match {
  case AbsentValue | NullValue => query.success
  case IntValue(n) if n == 0 => query.success
  case IntValue(n) if n > 0 => Offset(n, query).success
  case other => Result.failure(s"Expected offset >= 0, found $other")
}

def mkLimit(query: Query, v: Value): Result[Query] = v match {
  case AbsentValue | NullValue => query.success
  case IntValue(n) if n > 0 => Limit(n, query).success
  case other => Result.failure(s"Expected limit > 0, found $other")
}

def mkFilter(query: Query, tpe: Type, v: Value): Result[Query] = v match {
  case AbsentValue | NullValue => query.success
  case FilterValue(id) => Filter(Eql(tpe / "id", Const(id)), query).success
  case _ => Result.failure(s"Expected filter value, found $v")
}

// inside the elaborator, compose with a for-comprehension over Result:
Elab.transformChild(child =>
  for {
    fc <- mkFilter(child, ElemAType, filter)
    sc <- mkOrderBy(fc, order)(o => List(OrderSelection[Option[String]](ElemAType / "elemA", ascending = o.ascending)))
    oc <- mkOffset(sc, offset)
    lc <- mkLimit(oc, limit)
  } yield lc)

def elabItems: Elab[Unit] =
  Elab.transformChild { child =>
    val lim0 = if (hasHasMore) limit.map(_ + 1) else limit   // overfetch one extra row
    val items = FilterOrderByOffsetLimit(None, Some(List(OrderSelection(orderTerm, nullsLast = nullsHigh))), offset, lim0, child)
    if (hasHasMore) TransformCursor(genItems, items) else items
  }

def genItems(c: Cursor): Result[Cursor] =
  for {
    size  <- c.listSize
    elems <- c.asList(Seq)
  } yield if (limit.forall(size <= _)) c else ListTransformCursor(c, size - 1, elems.init)

