object CurrencyQueryHandler extends EffectHandler[F] {
  def runEffects(queries: List[(Query, Cursor)]): F[Result[List[Cursor]]] = {
    val countryCodes  = queries.map(_._2.fieldAs[String]("code2").toOption)
    val distinctCodes = queries.flatMap(_._2.fieldAs[String]("code2").toList).distinct

    val children0 = queries.traverse { case (query, parentCursor) =>
      Query.childContext(parentCursor.context, query).map(ctx => (ctx, parentCursor))
    }

    def unpackResults(res: Json): List[Json] = /* split the single service result per country */ ???

    (for {
      children <- ResultT(children0.pure[F])
      // ONE service call for the whole batch, no matter how many countries are in the result
      res      <- ResultT(currencyService.get(distinctCodes).map(_.success))
    } yield {
      unpackResults(res).zip(children).map { case (res, (childContext, parentCursor)) =>
        CirceCursor(childContext, res, Some(parentCursor), parentCursor.env)
      }
    }).value.widen
  }
}

object CountryQueryHandler extends EffectHandler[F] {
  val toCode = Map("BR" -> "BRA", "GB" -> "GBR", "NL" -> "NLD")
  def runEffects(queries: List[(Query, Cursor)]): F[Result[List[Cursor]]] =
    runGrouped(queries) {
      case (Select(_, _, child), cursors, indices) =>
        val codes = cursors.flatMap(_.fieldAs[Json]("countryCode").toOption.flatMap(_.asString)).map(toCode)
        val combinedQuery = Select("country", None, Filter(In(CountryType / "code", codes), child))
        (for {
          cursor  <- ResultT(sqlCursor(combinedQuery, Env.empty))         // one SQL round-trip
          cursor0 <- ResultT(mkListCursor(cursor, "country", None).pure[F])
          pcs     <- ResultT(partitionCursor(codes, cursor0).pure[F])     // split back per input
        } yield pcs.zip(indices)).value.widen
      case _ => Result.internalError("Continuation query has the wrong shape").pure[F].widen
    }

  // groups identical continuation queries, runs op once per group, restores original order
  def runGrouped(ts: List[(Query, Cursor)])(
      op: (Query, List[Cursor], List[Int]) => F[Result[List[(Cursor, Int)]]]): F[Result[List[Cursor]]] = {
    val groupedAndIndexed = ts.zipWithIndex.groupMap(_._1._1)(ti => (ti._1._2, ti._2)).toList
    val groupedResults = groupedAndIndexed.map { case (q, cis) =>
      val (cursors, indices) = cis.unzip; op(q, cursors, indices)
    }
    groupedResults.sequence.map(_.sequence.map(_.flatten.sortBy(_._2).map(_._1)))
  }
}

