def collectionItemJoin(q: Query, c: Cursor): Result[Query] =
  (c.focus, q) match {
    case (c: CollectionData.Collection, Select("items", _, child)) =>
      Group(c.itemIds.map(id =>
        Select("itemById",
          Unique(Filter(Eql(ItemType / "id", Const(id)), child))))).success
    case _ =>
      Result.internalError("Unexpected cursor focus type in collectionItemJoin")
